def icon(name):return f'<svg class="icon" viewBox="0 0 40 40" fill="none" stroke="currentColor" stroke-width="1.7" stroke-linecap="round" stroke-linejoin="round" aria-hidden="true"><path d="{paths[name]}"/></svg>'
brand=f'<a class="brand" href="index.html" aria-label="Heart to Heart Hope and Healing home">{icon("heart")}<span>HEART <i>to</i> HEART<small>HOPE &amp; HEALING</small></span></a>'
nav=[('index.html','Home'),('about.html','About'),('schedule.html','Group Sessions'),('resources.html','Resources'),('faq.html','FAQ'),('contact.html','Contact')]
def links(active):return ''.join(f'<a href="{url}"'+(' aria-current="page"' if url==active else '')+f'>{label}</a>' for url,label in nav)
def page(filename,title,body,script=None):
    # Forms stay inert until their JavaScript is ready; never fall back to GET.
    body=re.sub(r'<form\b([^>]*)>(.*?)</form>', r'<form method="post"\1><fieldset disabled data-form-fields>\2</fieldset></form>', body, flags=re.S)
    navhtml=links(filename)
    doc=f'''<!doctype html>
<html lang="en"><head><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><title>{e(title)} | Heart to Heart: Hope &amp; Healing</title>
<meta name="description" content="A compassionate, faith-centered support group with Sherée Bergman for understanding narcissistic abuse, attachment wounds, and healthier relationships.">
<meta name="theme-color" content="#650d29"><link rel="icon" href="assets/img/Logo/favicon-concept.png">
<link rel="preconnect" href="https://fonts.googleapis.com"><link rel="preconnect" href="https://fonts.gstatic.com" crossorigin><link href="https://fonts.googleapis.com/css2?family=Cormorant+Garamond:ital,wght@0,500;0,600;0,700;1,500;1,600&family=Lato:wght@400;700&display=swap" rel="stylesheet"><link rel="stylesheet" href="assets/css/main.css">
<script type="module" src="assets/js/site.js"></script>{f'<script type="module" src="assets/js/{script}.js"></script>' if script else ''}</head>
<body><a class="skip-link" href="#main">Skip to content</a>
<header class="site-header"><div class="container header-inner">{brand}<button class="menu-toggle" aria-controls="navigation" aria-expanded="false" aria-label="Open menu"><span></span><span></span><span></span></button><nav id="navigation" aria-label="Main navigation">{navhtml}</nav><a class="button header-join" href="schedule.html">Join a Session</a></div></header>
<main id="main">{body}</main>
<footer class="site-footer"><div class="container"><div class="footer-top">{brand}<nav aria-label="Footer navigation">{navhtml}</nav><a class="music-link" href="https://www.youtube.com/@PolarisFrequency" target="_blank" rel="noopener noreferrer" aria-label="PolarisFrequency on YouTube">{icon('music')}</a></div><div class="footer-bottom"><small>© <span data-year>2026</span> Heart to Heart: Hope &amp; Healing. All rights reserved.</small><div><a href="privacy.html">Privacy Policy</a><a href="terms.html">Terms of Use</a><a href="contact.html">Contact</a><a href="admin.html">Admin</a></div></div></div></footer>
</body></html>'''
    doc=doc.replace('All rights reserved.</small>', f'All rights reserved. · <span data-version>v{VERSION}</span></small>')
    (ROOT/filename).write_text(doc.replace('<br>', ' <br>'),encoding='utf-8')
def intro(eyebrow,title,desc):return f'<section class="page-intro"><div class="container"><p class="eyebrow">{eyebrow}</p><h1>{title}</h1><p>{desc}</p></div></section>'
def cta():return '<section class="closing-cta"><div class="container"><p class="eyebrow">Hope · Healing · Healthier Tomorrows</p><h2>Take the Next Step Toward a Brighter Tomorrow</h2><p>Find understanding, support, and practical tools in a safe and welcoming community.</p><a class="button light" href="schedule.html">Join a Session</a></div></section>'
headings={'From Pain to Purpose','A Journey Toward Healing','Why This Support Group Was Created','Professional Background','Author & Advocate for Healing','Turning Pain Into Purpose','Why This Support Group?','What You’ll Find Here',"What You'll Find Here"}
def paragraphs(key,start=1):
    out=[]
    for p in source[key][start:]:
        if p=='About Sherée':continue
        out.append(f'<h2>{e(p)}</h2>' if p in headings else f'<p>{e(p)}</p>')
    return ''.join(out)
home='''<section class="hero"><div class="container"><div class="hero-copy"><p class="eyebrow">Support · Education · Encouragement</p><h1>A Place for<br><span>Understanding,</span><br>Healing &amp; Hope</h1><p class="hero-subtitle">Support for those healing from narcissistic and emotional abuse, unhealthy relationship patterns, and attachment wounds.</p><p class="hero-description">You are not alone. Find understanding, practical tools, and a compassionate community as you rebuild your life and move toward healthier, more fulfilling relationships.</p><div class="actions"><a class="button" href="schedule.html">Join a Session</a><a class="button outline" href="#welcome">Learn More</a></div></div></div></section>'''
home+='<section class="pillars"><div class="container three-columns">'+''.join(f'<article class="pillar"><div class="icon-circle {tone}">{icon(i)}</div><h2>{title}</h2><p>{body}</p></article>' for i,title,body,tone in [('head','Understand','Gain insight into narcissistic and emotional abuse,<br>unhealthy relationship patterns,<br>and attachment wounds.','wine'),('leaf','Heal','Process your experiences, build<br>self-trust, and learn and work through with practical tools<br>for lasting change.','tan'),('mountain','Move Forward','Create healthier boundaries,<br>stronger relationships, and a more<br>hopeful, authentic future.','brown')])+'</div></section>'
questions=['Why do I keep ending up in the same type of relationship?','Was it really abuse, or am I overreacting?','How do I rebuild my self-confidence?','Why is it so hard to trust again?','Can I have healthy relationships in the future?','Where do I go from here?']
topics=[('shield','Setting and maintaining healthy boundaries'),('leaf','Rebuilding self-trust and confidence'),('people','Healthy communication skills'),('spark','Understanding and managing emotional triggers'),('book','Faith, encouragement, and personal growth'),('heart','Creating and maintaining healthier relationships')]
home+=f'<section class="understanding"><div class="container understanding-grid"><div class="questions"><h2>You Are Not Alone</h2><p class="eyebrow">Have you ever asked yourself...</p><ul>'+''.join(f'<li>{q}</li>' for q in questions)+'</ul><p>These are real questions, and you’re not alone in asking them.<br>Our support group offers a safe, non-judgmental place to find answers, support, and hope.</p></div><div class="topics"><p class="eyebrow">Topics We Cover</p><ul>'+''.join(f'<li>{icon(i)}<span>{t}</span></li>' for i,t in topics)+'</ul></div></div></section>'
home+=f'<section class="trust-strip"><div class="container trust-grid"><div class="trust-main"><div class="icon-circle wine">{icon("lock")}</div><div><h3>A Safe and Confidential Space</h3><p>Your privacy matters. Our group sessions are confidential, respectful, and built on trust so you can share openly and feel safe on your healing journey.</p><a class="text-link" href="confidentiality.html">Read our confidentiality agreement</a></div></div><div class="trust-small">{icon("people")}<div><p class="eyebrow">Real People. Real Support.</p><p>A welcoming, judgment-free community<br>with people who understand.</p></div></div></div></section>'
home+='''<section class="founder"><div class="container founder-grid"><img src="assets/img/Profile/sheree-portrait.jpg" alt="Sherée Bergman, founder of Heart to Heart" width="1165" height="1167" loading="lazy"><div><p class="eyebrow">Meet the Founder</p><h2>Meet Sherée</h2><p>Sherée is a compassionate advocate, group facilitator, and encourager for those healing from narcissistic and emotional abuse and unhealthy relationship patterns. With a heart for helping others find hope and wholeness, she brings both experience and empathy to every session. Sherée creates a safe, welcoming space where people can be real, find understanding, and take meaningful steps toward healing and a brighter future.</p><a class="button" href="about.html">Our Story</a></div><blockquote><span aria-hidden="true">“</span><p>Healing is possible.<br>Your story is not over,<br>Hope can be found in your next chapter.</p><cite>— Sherée</cite></blockquote></div></section>'''
home+='<section class="home-sessions"><div class="container"><div class="section-heading"><h2>Group Sessions</h2><p class="eyebrow">Two Convenient Times · Same Supportive Community</p></div><div class="session-pair">'
for kind,title,desc,i in [('morning','Morning Session','Start your day with encouragement,<br>insight, and community.','sun'),('evening','Evening Session','Unwind and find support at the<br>end of your day.','moon')]:
    home+=f'<article class="session-summary"><div class="photo-sprite {kind}-photo" role="img" aria-label="Mountain scenery at {kind}"></div><div>{icon(i)}<h3>{title}</h3><p>{desc}</p><p class="session-next" data-next="{kind}">Every two weeks · See upcoming dates</p><a class="button" href="schedule.html?session={kind}">Join {kind.title()} Session</a></div></article>'
home+='</div></div></section><section class="home-resources"><div class="container resource-preview"><div><h2>Helpful Resources</h2><p class="eyebrow">Books · Music · Tools for Your Journey</p><p>Explore trusted resources that can bring you insight, encouragement,<br>and practical help as you heal and grow.</p><div class="actions"><a class="button" href="resources.html">View All Resources</a><a class="button outline" href="resources.html#books">Recommended Reading</a></div></div><div class="resource-tiles">'
for kind,title,desc,href in [('books','Books','Insightful, healing, and<br>hope-filled reads.','resources.html#books'),('music','Music','Uplifting music for<br>reflection and peace.','resources.html#music'),('tools','Tools & Guides','Practical resources for<br>everyday growth.','resources.html#tools')]:home+=f'<a href="{href}"><div class="photo-sprite {kind}-photo" role="img" aria-label="{title}"></div><h3>{title}</h3><p>{desc}</p></a>'
