home+='<section id="welcome" class="container full-welcome"><details><summary>Welcome to Heart to Heart — read our full introduction</summary><div class="prose">'+paragraphs('Home Page')+'</div></details><p class="disclaimer">'+e(source['Home Page'][-1])+'</p></section>'
