agreement=source['SUPPORT GROUP CONFIDENTIALITY AGREEMENT']
agreement_headings={'Support & Education — Not Therapy', 'Confidentiality', 'Privacy Outside the Group', 'Leader & Co-Leaders Exception', 'CONFIDENTIALITY AGREEMENT', 'No Recording or Sharing', 'Limits of Confidentiality', 'Emergency & Crisis Situations', 'Personal Responsibility', 'Respect, Safety & Personal Choice', 'DISCLAIMER & AGREEMENT', 'Acknowledgment & Agreement'}
agreementhtml=''
