page('confidentiality.html','Support Group Confidentiality and Disclaimer Agreement',intro('Privacy · Respect · Trust','Support Group Confidentiality and Disclaimer Agreement','A shared commitment to a safe, private, and respectful environment, with clear expectations for participation.')+'<section class="container narrow section-space"><article class="prose agreement">'+agreementhtml+'<div class="signature-lines">'+''.join(f'<p>{e(p)}</p>' for p in agreement if p.startswith(('Name (Print):','Member (Signature):','Date:')))+'</div></article><div class="actions no-print"><button class="button" data-print>Print Agreement</button><a class="button outline" href="assets/files/SUPPORT%20GROUP%20CONFIDENTIALITY%20AGREEMENT.docx" download>Download Word Copy</a></div></section>')
page('privacy.html','Privacy Policy',intro('Your Information','Privacy Policy','How this website handles the information you choose to share.')+'''<article class="container narrow prose section-space"><h2>Information you provide</h2><p>When you RSVP, we collect your name, email address, and selected session. When you contact us, we collect your name, email address, subject, and message. We use this information to manage sessions, respond to you, and support group administration.</p><h2>Who can access it</h2><p>RSVPs and contact messages are accessible to authorized group administrators and are sent to the group’s private email inbox. Attendee lists are not displayed publicly. GitHub Pages hosts this website. Firebase provides authentication, database services, and secure form processing. Gmail processes notification emails sent to the group’s private inbox.</p><h2>Website operation</h2><p>Administrator sign-in uses browser storage for authentication. Public visitors do not need an account to RSVP. Hashed network identifiers and email-derived identifiers are used to limit repeated form submissions. Fonts load from Google Fonts. This website does not include advertising trackers or an analytics SDK.</p><h2>Your choices</h2><p>Share only the information you are comfortable sending. You can request correction or deletion of your RSVP or message through the <a href="contact.html">Contact page</a>. Administrators retain records for group administration until they are removed. Deleting a website record does not automatically delete copies already delivered to an email inbox.</p><h2>Group confidentiality</h2><p>The <a href="confidentiality.html">group confidentiality agreement</a> describes members’ responsibilities, leader guidance, recording restrictions, and the limits of confidentiality.</p><h2>Other websites</h2><p>Book and music links open external websites, which have their own privacy practices.</p></article>''')
page('terms.html','Terms of Use',intro('Our Shared Understanding','Terms of Use','Please read these alongside the group confidentiality agreement.')+'<article class="container narrow prose section-space"><h2>Purpose of the group</h2><p>'+e(source['Home Page'][-1])+'</p><h2>Respectful participation</h2><p>Participation is subject to the <a href="confidentiality.html">Support Group Confidentiality and Disclaimer Agreement</a>. Violating its privacy and respect guidelines may result in being asked to leave the group.</p><h2>Sessions and RSVPs</h2><p>The schedule shows currently published session information. Please check the listed date, time, timezone, and location. If your plans change or you have questions about a session, contact Sherée.</p><h2>Resources</h2><p>Books and music linked from this site are resources for reflection and encouragement. External sites manage their own content, purchases, and availability.</p></article>')
page('404.html','Page Not Found',intro('Let’s Find Your Way','This Page Couldn’t Be Found','You can return home or explore an upcoming session.')+'<div class="container section-space actions"><a class="button" href="index.html">Return Home</a><a class="button outline" href="schedule.html">View Sessions</a></div>')
admin=intro('Heart to Heart','Group Administration','Manage sessions, view RSVPs, and read contact messages.')+'''<section class="container section-space"><div id="auth-panel" class="form-card narrow"><h2>Administrator Sign In</h2><form id="login-form"><label>Email address<input type="email" name="email" autocomplete="username" required></label><label>Password<input type="password" name="password" autocomplete="current-password" required></label><button class="button" type="submit">Sign In</button><button class="text-button" type="button" id="reset-password">Reset password</button><p class="form-status" role="status"></p></form></div><p id="admin-status" role="status"></p>
<div id="admin-panel" hidden><div class="admin-toolbar"><p id="admin-identity"></p><button class="button outline" id="sign-out">Sign Out</button></div><div class="admin-tabs" role="group" aria-label="Administration views"><button class="filter active" data-tab="sessions" aria-pressed="true">Sessions &amp; RSVPs</button><button class="filter" data-tab="messages" aria-pressed="false">Contact Messages</button></div><section id="sessions-panel"><div class="admin-layout"><div class="form-card"><h2 id="editor-title">Create a Session</h2><form id="event-form"><input type="hidden" name="id"><input type="hidden" name="updatedAt"><label>Event name<input name="name" required maxlength="160"></label><label>Session<select name="session"><option value="morning">Morning</option><option value="evening">Evening</option></select></label><div class="two-columns"><label>Starts<input type="datetime-local" name="startLocal" required></label><label>Ends<input type="datetime-local" name="endLocal" required></label></div><label>Timezone<select name="timezone"><option value="America/Chicago">Central — America/Chicago</option><option value="America/New_York">Eastern — America/New_York</option><option value="America/Denver">Mountain — America/Denver</option><option value="America/Los_Angeles">Pacific — America/Los_Angeles</option><option value="America/Phoenix">Arizona — America/Phoenix</option><option value="America/Anchorage">Alaska — America/Anchorage</option><option value="Pacific/Honolulu">Hawaii — Pacific/Honolulu</option></select></label><label>Location name<input name="locationTitle" required maxlength="160"></label><label>Street address or online meeting instructions<textarea name="address" required maxlength="500" rows="2"></textarea></label><p class="form-note">Event details, including location, are publicly visible. Do not put private meeting passwords here.</p><label>Event description<textarea name="description" required maxlength="3000" rows="4"></textarea></label><label id="repeat-field">Number of sessions (every two weeks)<input type="number" name="occurrences" min="1" max="26" value="1" required></label><p class="form-note" id="repeat-note">Choose more than one to create a series. Each occurrence can then be edited independently.</p><label class="checkbox"><input name="rsvpOpen" type="checkbox" checked> Accept RSVPs</label><div class="actions"><button class="button" type="submit">Save Session</button><button class="button outline" id="cancel-edit" type="button">Clear Form</button></div><p class="form-status" role="status"></p></form></div><div><h2>Published Sessions</h2><label>Find a session<input id="event-search" type="search" placeholder="Search by name or location"></label><div id="admin-events"></div><section class="form-card" id="attendees-panel" hidden><h2 id="attendees-title">Attendees</h2><p class="form-note">Keep names and email addresses confidential.</p><div id="attendees-list"></div></section></div></div></section><section id="messages-panel" hidden><h2>Contact Messages</h2><div id="messages-list"></div></section></div></section>'''
